values ('MH-CASE-001', 'mh-case-001', (select id from public.categories where slug = 'cases'), 'جراب سيليكون ببطانة مخملية', 'Silicone case with soft velvet lining', 'جراب سيليكون ناعم من بره وبطانة مخملية من جوه بتحمي ضهر الموبايل من الخدوش. خفيف ومريح في الإيد.', 'Smooth silicone outside and a soft velvet lining inside that protects the back of your phone from scratches. Light and comfortable to hold.', 7900, 500, array['جراب','كفر','سيليكون','silicone','case','cover']::text[], 'published', false)
