 where p.sku = 'MH-WATC-002' and not exists (select 1 from public.product_images i where i.product_id = p.id and i.storage_path = 'https://images.unsplash.com/photo-1598516802414-50a01bee818d?auto=format&fit=crop&w=900&h=900&q=80');
insert into public.product_images(product_id, storage_path, alt_ar, alt_en, sort_order)
select p.id, 'https://images.unsplash.com/photo-1634878656461-bcf0b954d8b3?auto=format&fit=crop&w=900&h=900&q=80', p.name_ar, p.name_en, 1 from public.products p
 where p.sku = 'MH-MISC-001' and not exists (select 1 from public.product_images i where i.product_id = p.id and i.storage_path = 'https://images.unsplash.com/photo-1634878656461-bcf0b954d8b3?auto=format&fit=crop&w=900&h=900&q=80');
insert into public.product_images(product_id, storage_path, alt_ar, alt_en, sort_order)
select p.id, 'https://images.unsplash.com/photo-1573739022854-abceaeb585dc?auto=format&fit=crop&w=900&h=900&q=80', p.name_ar, p.name_en, 1 from public.products p
 where p.sku = 'MH-BNDL-001' and not exists (select 1 from public.product_images i where i.product_id = p.id and i.storage_path = 'https://images.unsplash.com/photo-1573739022854-abceaeb585dc?auto=format&fit=crop&w=900&h=900&q=80');

-- opening stock recorded once in the inventory log
insert into public.inventory_movements(product_id, delta, reason, note)
select p.id, p.stock_quantity, 'restock', 'opening stock (product sheet 2026-10)' from public.products p
 where p.sku like 'MH-%' and p.stock_quantity > 0
   and not exists (select 1 from public.inventory_movements m where m.product_id = p.id);

commit;
